SELECT id, user_id, event_type, title, content, link_route, link_params, is_read, read_at, email_status, zalo_status, created_at
FROM notification WHERE user_id = #{userId} AND is_read = 0
ORDER BY created_at DESC, id DESC LIMIT #{q.size} OFFSET #{q.offset}

